    def read_ints():
        return list(map(int, sys.stdin.readline().split()))

    def dfs(node, parent, xor_values, tree):
        xor_sum = 0
        for neighbor in tree[node]:
            if neighbor != parent:
                xor_sum ^= dfs(neighbor, node, xor_values, tree)
        xor_sum ^= xor_values[node]
        return xor_sum

    T = read_int()
    results = []

    for _ in range(T):
        N, K = read_ints()
        xor_values = read_ints()
        tree = defaultdict(list)

        for _ in range(N - 1):
            u, v = read_ints()
            tree[u - 1].append(v - 1)
            tree[v - 1].append(u - 1)

        xor_sums = []
        for i in range(N):
            xor_sums.append(dfs(i, -1, xor_values, tree))

        xor_sums.sort(reverse=True)
        max_and_value = xor_sums[0]
        for i in range(1, K):
            max_and_value &= xor_sums[i]

        results.append(max_and_value)

    for result in results:
        print(result)

if __name__ == "__main__":
